  "/** Conservatively counts every persistent signal/state cache and scalar lifecycle marker. */",
  "function m9StateElementCount(node: IRNode): number | undefined {",
  "    const p = node.parameters;",
  "    const width = node.outputs.out ? signalElementCount(node.outputs.out) : 1;",
  "    const initialWidth = (): number => signalElementCount(validateSignal(p.initial ?? 0));",
  "    const base = width + 2; // previousOutput, reset flag, publication/due marker",
  "    switch (node.blockType) {",
  "        case 'discrete.filter': {",
  "            const a = (p.denominator as number[]).length, b = p.representation === 'transfer' ? a : (p.numerator as number[]).length;",
  "            const slots = p.structure === 'df1' || p.structure === 'df1t' ? a + b - 2 : Math.max(a, b) - 1;",
  "            return base + (slots + 1) * initialWidth();",
  "        }",
  "        case 'discrete.filter-time-varying': return base + ((p.order as number) + 1) * initialWidth();",
  "        case 'discrete.zero-pole': return base + ((p.poles as number[]).length + 1) * initialWidth();",
  "        case 'discrete.pid':",
  "        case 'discrete.pid-2dof': return base + 8;",
  "        case 'discrete.delay-configured': return base + ((p.mode === 'variable' ? p.maxDelay : p.steps) as number) * initialWidth() + 2 * initialWidth() + 2;",
  "        case 'discrete.tapped-delay': return base + (p.taps as number) + 3;",
  "        case 'discrete.propagation-delay': return base + (p.capacity as number) * (initialWidth() + 2) + initialWidth() + 2; // value, physical arrival, integer due tick",
  "        case 'discrete.integrator-configured': return base + 3 * initialWidth();",
  "        case 'discrete.state-space-mimo': return base + (p.initial as number[]).length + width;",
  "        case 'discrete.difference-configured':",
  "        case 'logic.numeric-edge':",
  "        case 'math.running-minmax':",
  "        case 'verify.gradient': return base + 2 * initialWidth();",
  "        case 'signal.initial-condition': return base + initialWidth() + 1;",
  "        case 'source.band-limited-noise':",
  "        case 'source.random-configured': return base + width + 3;",
  "        case 'source.counter':",
  "        case 'source.signal-generator':",
  "        case 'source.sine-configured':",
  "        case 'source.sequence-configured': return base + width + 3;",
  "        case 'source.pwm':",
  "        case 'source.variable-pulse': return base + 8;",
  "        case 'time.weighted-math':",
  "        case 'time.decrement-to-zero':",
  "        case 'verify.resolution': return base + width; // bounded runtime publication cache",
  "        default: return undefined;",
  "    }",
  "}",
  "/** Logical persistent memory, excluding temporary atomic-commit copies. Input is validated IR. */",
  "function discreteStateElementCount(node: IRNode): number {",
  "    if (typeof node.parameters.m12DiscreteStateElements === 'number')",
  "        return node.parameters.m12DiscreteStateElements;",
  "    if (typeof node.parameters.scopeStateElements === 'number')",
  "        return node.parameters.scopeStateElements;",
  "    if (typeof node.parameters.m11StateElements === 'number')",
  "        return node.parameters.m11StateElements;",
  "    const m9Count = m9StateElementCount(node);",
  "    if (m9Count !== undefined)",
  "        return m9Count;",
  "    const initialCount = (): number => signalElementCount(validateSignal(node.parameters.initial));",
  "    switch (node.blockType) {",
  "        case 'fixed.state-space': return typedStorageElements(validateTypedSignal(node.parameters.initial));",
  "        case 'discrete.unit-delay':",
  "        case 'discrete.integrator':",
  "        case 'discrete.difference':",
  "        case 'discrete.derivative':",
  "        case 'time.rate-transition': return initialCount();",
  "        case 'discrete.delay': return (node.parameters.steps as number) * initialCount();",
  "        case 'discrete.fir': return Math.max(0, (node.parameters.coefficients as number[]).length - 1) * initialCount();",
  "        case 'discrete.transfer-function': return (node.parameters.numerator as number[]).length + (node.parameters.denominator as number[]).length - 2;",
  "        case 'discrete.state-space': return (node.parameters.initial as number[]).length;",
  "        case 'logic.edge-detect':",
  "        case 'source.random': return 1;",
  "        default: return 0;",
  "    }",
  "}",
  "function discreteMemoryElementCount(nodes: readonly IRNode[]): number {",
  "    return nodes.reduce((count, node) => count + discreteStateElementCount(node)",
  "        + Object.values(node.outputs).reduce((held, descriptor) => held + signalElementCount(descriptor), 0), 0);",
  "}",
  "const SOLVER_LIMITS = Object.freeze({",
  "    minStep: 1e-12, maxStep: 1e9, minTolerance: 1e-12, maxTolerance: 1,",
  "    maxSteps: 100000, maxRejects: 10000, maxEvaluations: 1000000,",
  "    maxEvents: 10000, minEventTolerance: 1e-12, maxEventTolerance: 1,",
  "});",
  "/** One bounded normalized solver contract shared by compiler, Worker, UI and exports. */",
  "function normalizeSolverSettings(execution: ExecutionSettings): SolverSettings {",
  "    const defaults: SolverSettings = {",
  "        method: 'rk4', initialStep: execution.step, minStep: Math.min(execution.step, 1e-8),",
  "        maxStep: execution.step, atol: 1e-8, rtol: 1e-6,",
  "        maxSteps: SOLVER_LIMITS.maxSteps, maxRejects: SOLVER_LIMITS.maxRejects,",
  "        maxEvaluations: SOLVER_LIMITS.maxEvaluations, eventTolerance: 1e-8,",
  "        maxEvents: SOLVER_LIMITS.maxEvents, discreteStep: execution.step,",
  "        ...(execution.solver?.method === 'implicit-euler' ? { newtonTolerance: 1e-9, newtonMaxIterations: 24, jacobianStep: 1e-6 } : {}),",
  "    };",
  "    const value = { ...defaults, ...execution.solver };",
  "    const invalid = (message: string): never => { throw new ModelError([{ code: 'INVALID_SOLVER', message }]); };",
  "    if (Object.keys(execution.solver ?? {}).some((key) => !Object.hasOwn(defaults, key)))",
  "        invalid('지원하지 않는 솔버 필드입니다.');",
  "    if (!['rk4', 'rk45', 'implicit-euler'].includes(value.method))",
  "        invalid('솔버는 rk4, rk45 또는 독립 implicit-euler여야 합니다.');",
  "    if (value.method === 'implicit-euler') {",
  "        if (!Number.isFinite(value.newtonTolerance) || value.newtonTolerance! < 1e-14 || value.newtonTolerance! > 1e-3)",
  "            invalid('newtonTolerance는1e-14~1e-3이어야 합니다.');",
  "        if (!Number.isSafeInteger(value.newtonMaxIterations) || value.newtonMaxIterations! < 1 || value.newtonMaxIterations! > 32)",
  "            invalid('newtonMaxIterations는1~32의 정수여야 합니다.');",
  "        if (!Number.isFinite(value.jacobianStep) || value.jacobianStep! < 1e-8 || value.jacobianStep! > 1e-2)",
  "            invalid('jacobianStep은1e-8~1e-2이어야 합니다.');",
  "    }",
  "    for (const key of ['initialStep', 'minStep', 'maxStep', 'discreteStep'] as const) {",
  "        const min = key === 'discreteStep' ? 1e-9 : SOLVER_LIMITS.minStep;",
  "        if (!Number.isFinite(value[key]) || value[key] < min || value[key] > SOLVER_LIMITS.maxStep)",
  "            invalid(`${key}는 ${min}~${SOLVER_LIMITS.maxStep}의 유한한 양수여야 합니다.`);",
  "    }",
  "    if (value.minStep > value.initialStep || value.initialStep > value.maxStep)",
  "        invalid('minStep ≤ initialStep ≤ maxStep이어야 합니다.');",
  "    for (const key of ['atol', 'rtol'] as const)",
  "        if (!Number.isFinite(value[key]) || value[key] < SOLVER_LIMITS.minTolerance || value[key] > SOLVER_LIMITS.maxTolerance)",
  "            invalid(`${key} 허용오차는 1e-12~1이어야 합니다.`);",
  "    if (!Number.isFinite(value.eventTolerance) || value.eventTolerance < SOLVER_LIMITS.minEventTolerance || value.eventTolerance > SOLVER_LIMITS.maxEventTolerance)",
  "        invalid('eventTolerance는 1e-12~1이어야 합니다.');",
  "    for (const key of ['maxSteps', 'maxRejects', 'maxEvaluations', 'maxEvents'] as const) {",
  "        const min = key === 'maxRejects' ? 0 : 1;",
  "        if (!Number.isSafeInteger(value[key]) || value[key] < min || value[key] > SOLVER_LIMITS[key])",
